-- 0048_ap_concept_library.sql
-- AP 개념정리: 일본어 기본 + 한국어 병기, 유형별 예상문제
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS ap_concepts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  concept_code TEXT NOT NULL UNIQUE,
  exam_part TEXT NOT NULL DEFAULT 'A' CHECK (exam_part IN ('A','B','AB')),
  unit_ko TEXT NOT NULL, unit_ja TEXT NOT NULL,
  title_ko TEXT NOT NULL, title_ja TEXT NOT NULL,
  definition_ko TEXT NOT NULL, definition_ja TEXT NOT NULL,
  principle_ko TEXT NOT NULL, principle_ja TEXT NOT NULL,
  key_points_ko TEXT NOT NULL, key_points_ja TEXT NOT NULL,
  method_ko TEXT NOT NULL, method_ja TEXT NOT NULL,
  traps_ko TEXT NOT NULL, traps_ja TEXT NOT NULL,
  memory_ko TEXT NOT NULL, memory_ja TEXT NOT NULL,
  example_ko TEXT NOT NULL, example_ja TEXT NOT NULL,
  sort_order INTEGER NOT NULL UNIQUE,
  is_published INTEGER NOT NULL DEFAULT 1 CHECK (is_published IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE IF NOT EXISTS ap_concept_problem_types (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  concept_id INTEGER NOT NULL,
  type_no INTEGER NOT NULL CHECK(type_no>0),
  type_name_ko TEXT NOT NULL, type_name_ja TEXT NOT NULL,
  sort_order INTEGER NOT NULL,
  UNIQUE(concept_id,type_no),
  FOREIGN KEY(concept_id) REFERENCES ap_concepts(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS ap_concept_questions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  problem_type_id INTEGER NOT NULL,
  question_no INTEGER NOT NULL CHECK(question_no>0),
  question_ko TEXT NOT NULL, question_ja TEXT NOT NULL,
  choices_ko_json TEXT, choices_ja_json TEXT,
  correct_choice INTEGER,
  answer_ko TEXT NOT NULL, answer_ja TEXT NOT NULL,
  explanation_ko TEXT NOT NULL, explanation_ja TEXT NOT NULL,
  difficulty INTEGER NOT NULL DEFAULT 2 CHECK(difficulty BETWEEN 1 AND 3),
  sort_order INTEGER NOT NULL,
  UNIQUE(problem_type_id,question_no),
  FOREIGN KEY(problem_type_id) REFERENCES ap_concept_problem_types(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_ap_concepts_published_order ON ap_concepts(is_published,sort_order);
CREATE INDEX IF NOT EXISTS idx_ap_problem_types_concept_order ON ap_concept_problem_types(concept_id,sort_order);
CREATE INDEX IF NOT EXISTS idx_ap_questions_type_order ON ap_concept_questions(problem_type_id,sort_order);

INSERT OR REPLACE INTO ap_concepts(concept_code,exam_part,unit_ko,unit_ja,title_ko,title_ja,definition_ko,definition_ja,principle_ko,principle_ja,key_points_ko,key_points_ja,method_ko,method_ja,traps_ko,traps_ja,memory_ko,memory_ja,example_ko,example_ja,sort_order,is_published) VALUES
('A-01','A','기초이론','基礎理論','2진수·16진수','2進数・16進数','2진수는 0과 1, 16진수는 0~9와 A~F를 사용하는 수 표현 방식이다. 비트 패턴을 사람이 읽기 쉽게 표현할 때 16진수를 자주 사용한다.','2進数は0と1、16進数は0～9とA～Fを使う数の表現方法である。bit列を人が読みやすく表すため16進数をよく使う。','각 자리값은 자리 숫자×밑의 거듭제곱이다. 2진수 1자리는 1bit, 16진수 1자리는 정확히 4bit에 대응한다.','各桁は桁値×基数の累乗で決まる。2進数1桁は1bit、16進数1桁はちょうど4bitに対応する。','2↔16진 변환은 4bit씩 묶는다. nbit 무부호 정수는 0~2^n-1이다. 10진→2진은 2로 나눈 나머지를 역순으로 읽는다.','2↔16進変換は4bitずつ区切る。n bit符号なし整数は0～2^n-1。10進→2進は2で割った余りを逆順に読む。','2진→10진은 1인 자리의 2^k를 합한다. 2진→16진은 오른쪽부터 4자리씩 묶고, 16진→2진은 한 자리를 4bit로 바꾼다.','2進→10進は1の桁の2^kを加算。2進→16進は右から4桁ずつ区切り、16進→2進は各1桁を4bitへ変換する。','왼쪽부터 2^0으로 두는 실수, A=10~F=15를 잊는 실수, 4bit 묶음의 선행 0을 잘못 처리하는 함정이 많다.','左端を2^0とするミス、A=10～F=15を忘れるミス、4bit区切りの先頭0の扱いに注意する。','16진수 1자리=2진수 4자리. 1·2·4·8 자리값을 먼저 적는다.','16進数1桁=2進数4桁。1・2・4・8の重みを先に書く。','101101₂=32+8+4+1=45₁₀=2D₁₆.','101101₂=32+8+4+1=45₁₀=2D₁₆。',1,1),
('A-02','A','기초이론','基礎理論','2의 보수','2の補数','2의 보수는 고정 bit에서 음수를 표현하는 대표 방식이다. 최상위 bit가 1이면 음수로 해석한다.','2の補数は固定bit幅で負数を表す代表方式。最上位bitが1なら負数として解釈する。','nbit에서 -x는 2^n-x이며, 양수 bit를 모두 반전하고 1을 더해 같은 표현을 얻는다.','n bitで-xは2^n-x。正数の全bitを反転し1を加えて同じ表現を得る。','nbit 범위는 -2^(n-1)~2^(n-1)-1. 반전+1로 부호를 바꿀 수 있다. 같은 부호끼리 더해 결과 부호가 바뀌면 overflow를 의심한다.','n bit範囲は-2^(n-1)～2^(n-1)-1。反転+1で符号を変換。同符号加算で結果符号が変わればoverflowを疑う。','8bit -18: 18=00010010→11101101→+1=11101110. 범위 문제는 bit 수부터 확인한다.','8bit -18：18=00010010→11101101→+1=11101110。範囲問題はbit数を最初に確認する。','부호 bit만 바꾸는 것은 2의 보수가 아니다. 8bit 10000000은 +128이 아니라 -128이다.','符号bitだけ変えるのは2の補数ではない。8bit 10000000は+128ではなく-128。','뒤집고 +1, 그리고 음수 범위가 양수보다 하나 더 많다.','反転して+1、負数側が一つ多い。','8bit에서 +127+1은 실제 +128을 표현할 수 없어 overflow다.','8bitで+127+1は本来の+128を表現できずoverflowとなる。',2,1),
('A-03','A','기초이론','基礎理論','논리연산','論理演算','AND·OR·XOR·NOT은 참/거짓 또는 bit 0/1을 규칙에 따라 계산하는 기본 논리연산이다.','AND・OR・XOR・NOTは真偽またはbit 0/1を規則に従って計算する基本論理演算。','AND는 둘 다 1, OR은 하나라도 1, XOR은 서로 다를 때 1, NOT은 0↔1 반전이다.','ANDは両方1、ORはいずれか1、XORは異なると1、NOTは0↔1反転。','AND는 bit 남기기, OR은 bit 켜기, XOR은 toggle에 자주 쓴다. De Morgan: ¬(A∧B)=¬A∨¬B, ¬(A∨B)=¬A∧¬B.','ANDはbit抽出、ORはbit設定、XORはtoggleに使う。De Morgan：¬(A∧B)=¬A∨¬B、¬(A∨B)=¬A∧¬B。','진리표는 00,01,10,11을 전부 적고, bit열은 자릿수를 맞춰 열별로 계산한다.','真理値表は00,01,10,11を全て書き、bit列は桁をそろえて列ごとに計算する。','XOR에서 1 XOR 1=0이다. De Morgan에서는 NOT만 붙이는 것이 아니라 AND↔OR도 바뀐다.','XORでは1 XOR 1=0。De Morganでは否定だけでなくAND↔ORも変わる。','AND=공통, OR=하나라도, XOR=다른 것만, NOT=반대.','AND=共通、OR=どちらか、XOR=異なるものだけ、NOT=反転。','1010 AND 1100=1000, OR=1110, XOR=0110.','1010 AND 1100=1000、OR=1110、XOR=0110。',3,1),
('A-04','A','기초이론','基礎理論','확률','確率','확률은 특정 사건이 일어날 가능성을 0~1로 나타낸 값이다. AP에서는 독립사건, 합사건, 조건부확률, 기대값 계산이 중요하다.','確率は事象が起こる可能性を0～1で表す。APでは独立事象、和事象、条件付き確率、期待値が重要。','독립 A,B가 동시에 발생할 확률은 P(A)P(B). 적어도 하나는 1-P(전부 실패). P(A|B)=P(A∩B)/P(B).','独立A,Bの同時発生はP(A)P(B)。少なくとも一つは1-P(全部失敗)。P(A|B)=P(A∩B)/P(B)。','겹칠 수 있는 합사건은 P(A∪B)=P(A)+P(B)-P(A∩B). 기대값은 결과값×확률의 합이다.','重なり得る和事象はP(A∪B)=P(A)+P(B)-P(A∩B)。期待値は値×確率の総和。','먼저 독립 조건인지 확인한다. 적어도 하나는 여사건으로, 조건부는 분모가 조건 사건임을 확인한다.','まず独立条件を確認。少なくとも一つは余事象、条件付きは分母が条件事象であることを確認する。','서로 배반과 독립은 다르다. 배반은 동시 발생 불가, 독립은 서로 확률에 영향을 주지 않는다는 뜻이다.','排反と独立は異なる。排反は同時発生不可、独立は互いの確率に影響しない。','적어도 하나=1-아무것도 안 일어남.','少なくとも一つ=1-一つも起こらない。','독립 장치 정상확률 0.9,0.8이면 둘 다 정상은 0.72.','独立装置の正常率0.9,0.8なら両方正常は0.72。',4,1),
('A-05','A','기초이론','基礎理論','정보량·엔트로피','情報量・エントロピー','정보량은 드문 사건일수록 더 큰 정보를 준다는 개념을 수치화한 것이고 엔트로피는 평균 정보량이다.','情報量は珍しい事象ほど大きな情報を与える考えを数値化したもの。entropyは平均情報量。','확률 p의 자기정보량 I=-log2 p=log2(1/p), 엔트로피 H=-Σp log2 p. 결과가 균등할수록 엔트로피가 커진다.','確率pの自己情報量I=-log2 p、entropy H=-Σp log2 p。結果が均等なほどentropyは大きい。','1/2→1bit, 1/4→2bit, 1/8→3bit를 즉시 계산한다. n개 균등 결과는 log2 n bit.','1/2→1bit、1/4→2bit、1/8→3bitを即答。n個等確率ならlog2 n bit。','각 사건의 정보량을 구해 확률을 곱한 뒤 합한다. 계산 전 확률 합이 1인지 확인한다.','各事象の情報量を求め確率を掛けて合計。先に確率合計が1か確認する。','확률이 높을수록 정보량이 크다는 선택지는 반대다. 확률 1인 사건은 정보량 0이다.','確率が高いほど情報量が大きいという選択肢は逆。確率1の事象は0bit。','희귀할수록 정보량 큼, 균등할수록 엔트로피 큼.','珍しいほど情報量大、均等ほどentropy大。','확률 1/2,1/4,1/4의 엔트로피는 1.5bit.','確率1/2,1/4,1/4のentropyは1.5bit。',5,1),
('A-06','A','기초이론','基礎理論','부동소수점·오차','浮動小数点・誤差','부동소수점은 실수를 부호·지수·가수로 나눠 제한된 bit 안에 근사 표현하는 방식이다.','浮動小数点は実数を符号・指数・仮数に分け、限られたbitで近似表現する方式。','m×b^e 형태로 정규화해 저장한다. 가수 bit는 정밀도, 지수 bit는 표현 가능한 크기 범위에 크게 영향을 준다.','m×b^eへ正規化して格納。仮数bitは精度、指数bitは表現範囲に大きく影響する。','큰 수+아주 작은 수에서는 情報落ち, 비슷한 큰 수의 뺄셈에서는 桁落ち가 발생하기 쉽다. 범위를 넘으면 overflow/underflow다.','大きい数+非常に小さい数では情報落ち、近い大数の減算では桁落ちが起こりやすい。範囲外はoverflow/underflow。','문제에서 부호→지수→가수 배치를 먼저 표시하고, 오차는 어떤 연산에서 생겼는지로 종류를 판단한다.','符号→指数→仮数の配置を先に確認し、誤差はどの演算で生じたかで種類を判断する。','情報落ち와 桁落ち를 바꿔 고르는 함정이 많다. underflow는 0과 같은 뜻이 아니라 너무 작은 절댓값 문제다.','情報落ちと桁落ちを逆に選ぶ罠が多い。underflowは単に0という意味ではなく小さすぎる絶対値の問題。','큰+작은=情報落ち, 비슷한 수 빼기=桁落ち.','大+小=情報落ち、近い数の差=桁落ち。','큰 값에 매우 작은 값을 더하면 가수 유효범위 밖으로 작은 값이 밀려 사라질 수 있다.','大きい値に非常に小さい値を足すと仮数の有効範囲外へ押し出され消えることがある。',6,1),
('A-07','A','알고리즘','アルゴリズム','Big-O','Big-O記法','Big-O는 입력 n이 커질 때 알고리즘 처리량의 증가율을 나타내는 표기다.','Big-Oは入力nが大きくなるときの処理量の増加率を表す記法。','상수배와 낮은 차수는 생략한다. 3n+10→O(n), 2n²+n→O(n²), 매번 절반이면 O(log n).','定数倍と低次項を省略。3n+10→O(n)、2n²+n→O(n²)、毎回半分ならO(log n)。','증가율은 O(1)<O(log n)<O(n)<O(n log n)<O(n²)<O(2^n). 중첩 loop는 실제 반복 횟수를 계산한다.','増加率はO(1)<O(log n)<O(n)<O(n log n)<O(n²)<O(2^n)。nest loopは実反復回数を数える。','연속 블록은 더해 지배항만 남기고, 중첩은 반복 횟수를 곱한다. i*=2는 log n이다.','連続blockは足して支配項だけ残し、nestは反復回数を掛ける。i*=2はlog n。','Big-O는 실제 초 단위 시간이 아니다. n이 작으면 상수항 때문에 실측속도 순서가 다를 수 있다.','Big-Oは実時間秒ではない。nが小さいと定数項で実測順が異なる場合がある。','연속=더해 큰 것, 중첩=곱, 절반=log.','連続=足して最大、nest=掛ける、半分=log。','n×n 중첩 loop는 n²회 실행되어 O(n²).','n×nの二重loopはn²回でO(n²)。',7,1),
('A-08','A','알고리즘','アルゴリズム','선형탐색','線形探索','선형탐색은 처음부터 차례대로 목표값과 비교하는 가장 단순한 탐색법이다.','線形探索は先頭から順に目的値と比較する最も単純な探索法。','정렬 여부와 무관하게 사용한다. 첫 원소면 1회, 없거나 마지막이면 n회 비교해 최악 O(n).','整列不要。先頭なら1回、存在しないか末尾ならn回比較し最悪O(n)。','작은 데이터나 한 번만 검색할 때 단순하고 유리할 수 있다. 성공 위치가 균등하면 평균 비교 횟수는 약 (n+1)/2.','小規模/一度だけの検索では単純で有利な場合がある。成功位置が一様なら平均比較回数は約(n+1)/2。','의사코드를 한 줄씩 추적하며 비교가 증가하는 시점을 센다. sentinel을 써도 점근복잡도는 O(n).','疑似コードを1行ずつtraceし比較回数を数える。番兵法でも漸近計算量はO(n)。','선형탐색 자체 비용과 정렬 후 반복검색의 전체 비용을 혼동하지 않는다.','線形探索自体の費用と整列後の反復検索の総費用を混同しない。','정렬 필요 없음, 앞에서 하나씩, 최악 n번.','整列不要、先頭から一つずつ、最悪n回。','[7,2,9,4]에서 9는 3회 비교한다.','[7,2,9,4]で9は3回比較する。',8,1),
('A-09','A','알고리즘','アルゴリズム','이분탐색','二分探索','이분탐색은 정렬된 데이터의 가운데와 비교하며 탐색 범위를 절반씩 버리는 탐색법이다.','二分探索は整列済みデータの中央と比較し探索範囲を半分ずつ捨てる探索法。','오름차순에서 target<mid이면 오른쪽을 버리고 target>mid이면 왼쪽을 버린다. O(log n).','昇順でtarget<midなら右、target>midなら左を捨てる。O(log n)。','정렬이 필수다. low/high/mid의 포함 규칙을 일관되게 써야 off-by-one과 무한 loop를 피한다.','整列が必須。low/high/midの包含規則を一貫させoff-by-oneや無限loopを防ぐ。','while low<=high라면 mid=floor((low+high)/2), 작으면 low=mid+1, 크면 high=mid-1.','while low<=highならmid=floor((low+high)/2)、小ならlow=mid+1、大ならhigh=mid-1。','미정렬 배열에 바로 적용하는 선택지가 대표 함정이다. 최악 비교횟수 표현은 문제의 경계 정의를 확인한다.','未整列配列へ直接適用する選択肢が代表的な罠。最悪比較回数は設問の境界定義を確認する。','정렬+반씩 제거=log.','整列+半分ずつ除外=log。','[2,5,8,12,16,23,38]에서 16은 12→23→16 순으로 찾는다.','[2,5,8,12,16,23,38]で16は12→23→16の順に発見。',9,1),
('A-10','A','알고리즘','アルゴリズム','스택·큐','スタック・キュー','스택은 LIFO, 큐는 FIFO 자료구조다.','StackはLIFO、QueueはFIFOのデータ構造。','Stack push/pop은 top에서, Queue enqueue는 rear, dequeue는 front에서 수행한다. 기본 연산은 보통 O(1).','Stack push/popはtop、Queue enqueueはrear、dequeueはfront。基本操作は通常O(1)。','Stack은 함수호출·괄호검사·DFS, Queue는 작업대기열·BFS에 자주 사용한다. 원형 Queue도 빈출이다.','Stackは関数呼出し・括弧・DFS、Queueは待ち行列・BFSに頻出。循環Queueも重要。','연산열은 매 연산 뒤 상태를 기록한다. 원형 Queue index는 (i+1)%N 형태로 이동한다.','操作列は各操作後の状態を書く。循環Queue indexは(i+1)%Nで進める。','Stack/Queue 꺼내는 방향을 반대로 고르는 함정과 원형 Queue의 empty/full 표현 방식을 주의한다.','Stack/Queueの取り出し方向を逆にする罠、循環Queueのempty/full表現方式に注意。','Stack=접시, Queue=줄서기.','Stack=皿、Queue=行列。','A,B,C를 Stack에서 pop하면 C부터, Queue에서 dequeue하면 A부터 나온다.','A,B,CならStackはCから、QueueはAから取り出す。',10,1),
('A-11','A','알고리즘','アルゴリズム','트리·이진탐색트리','木・二分探索木','트리는 부모-자식 계층구조이며 BST는 왼쪽<노드<오른쪽 규칙의 이진트리다.','木は親子の階層構造。BSTは左<node<右の規則を持つ二分木。','root는 부모 없음, leaf는 자식 없음. 균형 BST 탐색은 O(log n), 한쪽으로 치우치면 O(n).','rootは親なし、leafは子なし。平衡BST探索はO(log n)、片寄るとO(n)。','BST inorder는 오름차순. preorder=root-left-right, inorder=left-root-right, postorder=left-right-root.','BST inorderは昇順。preorder=root-left-right、inorder=left-root-right、postorder=left-right-root。','삽입은 root부터 비교해 작으면 왼쪽, 크면 오른쪽 빈 위치까지 내려간다.','挿入はrootから比較し、小なら左、大なら右の空位置まで進む。','이진트리라고 모두 BST는 아니다. 완전이진트리 높이와 임의 BST 높이를 같다고 보면 안 된다.','二分木が全てBSTではない。完全二分木の高さと任意BSTの高さを同一視しない。','BST=왼쪽 작고 오른쪽 큼, inorder=작은 것부터.','BST=左小・右大、inorder=小さい順。','50에 30,70,20,40을 넣으면 30/70은 좌우, 20/40은 30의 좌우다.','50へ30,70,20,40を入れると30/70は左右、20/40は30の左右。',11,1),
('A-12','A','알고리즘','アルゴリズム','그래프 BFS·DFS','グラフ BFS・DFS','그래프는 정점과 간선으로 관계를 표현하며 BFS는 폭 우선, DFS는 깊이 우선 탐색이다.','Graphは頂点と辺で関係を表し、BFSは幅優先、DFSは深さ優先探索。','BFS는 Queue, DFS는 Stack/재귀. 인접리스트 기준 둘 다 O(V+E). 무가중 그래프 최단 간선수는 BFS가 보장한다.','BFSはQueue、DFSはStack/再帰。隣接listならO(V+E)。重みなし最短辺数はBFSが保証。','visited를 추가 시점에 표시하면 중복 삽입을 줄인다. 방문순서는 인접 정점 나열순서에 따라 달라질 수 있다.','visitedを追加時に付けると重複挿入を減らせる。訪問順は隣接頂点の列挙順で変わり得る。','BFS는 Queue/distance, DFS는 호출 Stack/방문순서를 표로 추적한다.','BFSはQueue/distance、DFSはcall Stack/訪問順を表でtraceする。','최단경로라는 말만 보고 BFS를 고르면 안 된다. 서로 다른 양의 가중치가 있으면 Dijkstra 등이 필요하다.','最短経路という語だけでBFSを選ばない。異なる正重みがあればDijkstra等が必要。','BFS=Breadth=Queue, DFS=Depth=Stack/재귀.','BFS=Breadth=Queue、DFS=Depth=Stack/再帰。','0:[1,2],1:[3],2:[4]에서 BFS는 0,1,2,3,4 순이다.','0:[1,2],1:[3],2:[4]でBFSは0,1,2,3,4順。',12,1),
('A-13','A','알고리즘','アルゴリズム','정렬','整列アルゴリズム','정렬은 데이터를 key 순서로 재배치하는 처리이며 AP에서는 trace, 계산량, 안정성, 추가공간을 비교한다.','整列はデータをkey順へ並べ替える処理。APではtrace、計算量、安定性、追加領域を比較する。','Bubble/Selection/Insertion 기본은 O(n²). Merge는 O(n log n), Quick은 평균 O(n log n)·최악 O(n²), Heap은 O(n log n).','Bubble/Selection/Insertion基本はO(n²)。MergeはO(n log n)、Quickは平均O(n log n)・最悪O(n²)、HeapはO(n log n)。','거의 정렬된 작은 배열은 Insertion이 유리할 수 있다. Stable sort는 동일 key의 원래 상대순서를 유지한다.','ほぼ整列済みの小配列ではInsertionが有利な場合がある。Stable sortは同一keyの相対順を維持する。','trace는 문제의 의사코드와 pass 정의를 그대로 따른다. Quick은 pivot 규칙에 따라 중간상태가 달라진다.','traceは設問の疑似コードとpass定義に従う。Quickはpivot規則で途中状態が変わる。','Quick을 항상 O(n log n)이라고 고르는 함정이 많다. Selection은 교환이 적어도 비교는 O(n²).','Quickを常にO(n log n)とする罠が多い。Selectionは交換が少なくても比較O(n²)。','기본3종 n², Merge/Heap n log n, Quick 평균 n log n·최악 n².','基本3種n²、Merge/Heap n log n、Quick平均n log n・最悪n²。','[5,1,4,2] Bubble 첫 pass에서 가장 큰 5가 끝으로 이동한다.','[5,1,4,2]のBubble 1 passで最大5が末尾へ移動。',13,1);

