-- 각 유형의 기본 예상문제. 동일 유형의 추가 문제는 같은 problem_type_id에 question_no만 늘려 확장한다.
INSERT OR REPLACE INTO ap_concept_questions(problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT id,1,'101101₂를 10진수로 바꾸면?','101101₂を10進数に変換するとどれか。','["43","44","45","46"]','["43","44","45","46"]',2,'45','45','32+8+4+1=45.','32+8+4+1=45。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-01') AND type_no=1;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'0~1000을 모두 표현하려면 최소 몇 bit가 필요한가?','0～1000を全て表すために最低何bit必要か。','["9","10","11","12"]','["9","10","11","12"]',1,'10bit','10bit','2^9=512는 부족하고 2^10=1024로 0~1023을 표현한다.','2^9=512では不足し、2^10=1024で0～1023を表せる。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-01') AND type_no=2;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'11110000₂의 16진수 표현은?','11110000₂の16進数表現はどれか。','["E0","F0","0F","FF"]','["E0","F0","0F","FF"]',1,'F0','F0','1111=F, 0000=0이므로 F0.','1111=F、0000=0なのでF0。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-01') AND type_no=3;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'8bit에서 -18의 2의 보수는?','8bitで-18の2の補数表現はどれか。','["11101110","11101101","10010010","00010010"]','["11101110","11101101","10010010","00010010"]',0,'11101110','11101110','18=00010010을 반전해 11101101, +1하면 11101110.','18=00010010を反転し11101101、+1で11101110。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-02') AND type_no=1;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'8bit 2의 보수 정수 범위는?','8bit 2の補数整数の範囲はどれか。','["-127~127","-128~127","-128~128","0~255"]','["-127~127","-128~127","-128~128","0~255"]',1,'-128~127','-128～127','-2^7~2^7-1이다.','-2^7～2^7-1である。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-02') AND type_no=2;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'8bit에서 100+40의 결과는?','8bitで100+40の結果はどうなるか。','["정상","overflow","underflow","0"]','["正常","overflow","underflow","0"]',1,'overflow','overflow','8bit signed 최대 127보다 실제 합 140이 크다.','8bit signed最大127を実際の和140が超える。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-02') AND type_no=3;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'A=1,B=1일 때 A XOR B는?','A=1,B=1のときA XOR Bはどれか。','["0","1","A","B"]','["0","1","A","B"]',0,'0','0','XOR은 서로 다를 때만 1이다.','XORは異なるときだけ1。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-03') AND type_no=1;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'x의 하위 4bit만 남길 AND mask는?','xの下位4bitだけ残すAND maskはどれか。','["00001111","11110000","11111111","00000000"]','["00001111","11110000","11111111","00000000"]',0,'00001111','00001111','AND에서 남길 위치를 1로 둔다.','ANDでは残す位置を1にする。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-03') AND type_no=2;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'¬(A∧B)와 동치인 것은?','¬(A∧B)と等価なのはどれか。','["¬A∧¬B","¬A∨¬B","A∨B","A⊕B"]','["¬A∧¬B","¬A∨¬B","A∨B","A⊕B"]',1,'¬A∨¬B','¬A∨¬B','De Morgan에서 AND가 OR로 바뀐다.','De MorganでANDがORへ変わる。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-03') AND type_no=3;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'독립 A,B 성공확률이 0.8,0.9일 때 둘 다 성공할 확률은?','独立A,Bの成功率が0.8,0.9のとき両方成功する確率は?','["0.17","0.72","0.80","0.98"]','["0.17","0.72","0.80","0.98"]',1,'0.72','0.72','독립 동시발생은 0.8×0.9=0.72.','独立な同時発生は0.8×0.9=0.72。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-04') AND type_no=1;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'P(A∩B)=0.2, P(B)=0.5일 때 P(A|B)는?','P(A∩B)=0.2、P(B)=0.5のときP(A|B)は?','["0.1","0.2","0.4","0.7"]','["0.1","0.2","0.4","0.7"]',2,'0.4','0.4','0.2/0.5=0.4.','0.2/0.5=0.4。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-04') AND type_no=2;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'100원을 받을 확률 0.3, 0원 확률 0.7의 기대값은?','100円を得る確率0.3、0円0.7の期待値は?','["30","50","70","100"]','["30","50","70","100"]',0,'30','30','100×0.3+0×0.7=30.','100×0.3+0×0.7=30。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-04') AND type_no=3;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'확률 1/8인 사건의 자기정보량은?','確率1/8の事象の自己情報量は?','["1bit","2bit","3bit","8bit"]','["1bit","2bit","3bit","8bit"]',2,'3bit','3bit','-log2(1/8)=3.','-log2(1/8)=3。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-05') AND type_no=1;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'확률 1/2,1/4,1/4의 엔트로피는?','確率1/2,1/4,1/4のentropyは?','["1","1.25","1.5","2"]','["1","1.25","1.5","2"]',2,'1.5bit','1.5bit','0.5×1+0.25×2+0.25×2=1.5.','0.5×1+0.25×2+0.25×2=1.5。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-05') AND type_no=2;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'4개 결과에서 엔트로피가 최대인 분포는?','4結果でentropyが最大の分布は?','["1,0,0,0","0.7,0.1,0.1,0.1","0.25,0.25,0.25,0.25","0.4,0.3,0.2,0.1"]','["1,0,0,0","0.7,0.1,0.1,0.1","0.25,0.25,0.25,0.25","0.4,0.3,0.2,0.1"]',2,'균등분포','一様分布','동일 개수의 결과에서는 균등할수록 불확실성이 최대다.','同じ結果数では一様分布で不確実性が最大。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-05') AND type_no=3;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'가수부 bit 수가 주로 영향을 주는 것은?','仮数部bit数が主に影響するものは?','["정밀도","부호","정렬","주소"]','["精度","符号","sort","address"]',0,'정밀도','精度','가수부는 유효숫자의 정밀도를 결정한다.','仮数部は有効数字の精度を決める。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-06') AND type_no=1;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'큰 수에 매우 작은 수를 더해 작은 값이 사라지는 것은?','大数に非常に小さい数を加え小さい値が消えるのは?','["桁落ち","情報落ち","overflow","deadlock"]','["桁落ち","情報落ち","overflow","deadlock"]',1,'情報落ち','情報落ち','작은 수가 가수의 유효자리 밖으로 밀린다.','小さい値が仮数の有効桁外へ押し出される。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-06') AND type_no=2;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'표현 가능한 최대 절댓값을 넘는 현상은?','表現可能な最大絶対値を超える現象は?','["underflow","overflow","桁落ち","丸め"]','["underflow","overflow","桁落ち","丸め"]',1,'overflow','overflow','표현범위 상단을 넘는다.','表現範囲上限を超える。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-06') AND type_no=3;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'O(n) 블록 뒤 O(n²) 블록이 실행되면 전체 Big-O는?','O(n)の後にO(n²)が実行される全体Big-Oは?','["O(n)","O(n²)","O(n³)","O(2n²)"]','["O(n)","O(n²)","O(n³)","O(2n²)"]',1,'O(n²)','O(n²)','연속 비용을 더한 뒤 지배항 n²만 남긴다.','連続費用を足し支配項n²だけ残す。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-07') AND type_no=1;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'i=1에서 매번 i*=2로 n까지 반복하면?','i=1から毎回i*=2でnまで反復すると?','["O(1)","O(log n)","O(n)","O(n²)"]','["O(1)","O(log n)","O(n)","O(n²)"]',1,'O(log n)','O(log n)','2^k≈n이므로 k≈log2 n.','2^k≈nなのでk≈log2 n。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-07') AND type_no=2;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'n이 클 때 가장 느리게 증가하는 것은?','nが大きいとき最も遅く増加するのは?','["O(n²)","O(n log n)","O(log n)","O(n)"]','["O(n²)","O(n log n)","O(log n)","O(n)"]',2,'O(log n)','O(log n)','log n이 가장 완만하다.','log nが最も緩やか。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-07') AND type_no=3;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'[4,8,1,7,3]에서 7을 선형탐색하면 비교횟수는?','[4,8,1,7,3]から7を線形探索する比較回数は?','["2","3","4","5"]','["2","3","4","5"]',2,'4회','4回','4→8→1→7 순으로 네 번 비교한다.','4→8→1→7の4回比較。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-08') AND type_no=1;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'성공 위치가 균등한 n개 배열의 평균 비교횟수는?','成功位置が一様なn要素配列の平均比較回数は?','["1","log n","(n+1)/2","n²/2"]','["1","log n","(n+1)/2","n²/2"]',2,'(n+1)/2','(n+1)/2','1~n 비교횟수의 평균이다.','1～nの比較回数の平均。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-08') AND type_no=2;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'선형탐색의 장점은?','線形探索の利点は?','["정렬 필수","정렬 없이 사용 가능","항상 O(1)","중복 불가"]','["整列必須","整列なしで使用可能","常にO(1)","重複不可"]',1,'정렬 없이 사용 가능','整列なしで使用可能','앞에서부터 비교하므로 사전 정렬이 필요 없다.','先頭から比較するため事前整列不要。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-08') AND type_no=3;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'이분탐색의 필수 전제는?','二分探索の必須前提は?','["정렬됨","중복 없음","n이 짝수","Queue 사용"]','["整列済み","重複なし","nが偶数","Queue使用"]',0,'정렬됨','整列済み','비교 후 버릴 절반을 결정하려면 정렬 규칙이 필요하다.','比較後に捨てる半分を決めるには整列規則が必要。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-09') AND type_no=1;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'오름차순에서 target>a[mid]이면?','昇順でtarget>a[mid]なら?','["high=mid-1","low=mid+1","mid=0","종료"]','["high=mid-1","low=mid+1","mid=0","終了"]',1,'low=mid+1','low=mid+1','mid와 왼쪽은 후보가 아니므로 제거한다.','midと左側を候補から除外する。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-09') AND type_no=2;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'1024=2^10개 원소의 이분탐색 비교 규모는?','1024=2^10要素の二分探索の比較規模は?','["10회 정도","100회","512회","1024회"]','["約10回","100回","512回","1024回"]',0,'약 10회','約10回','범위를 10번 정도 절반으로 줄이면 1개 수준이 된다.','約10回半分にすると1要素程度になる。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-09') AND type_no=3;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'Stack에 A,B,C push 후 pop 값은?','StackにA,B,Cをpush後popする値は?','["A","B","C","없음"]','["A","B","C","なし"]',2,'C','C','LIFO이므로 마지막 C가 먼저 나온다.','LIFOなので最後のCが先。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-10') AND type_no=1;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'BFS 구현에 대표적으로 쓰는 자료구조는?','BFS実装で代表的に使うデータ構造は?','["Stack","Queue","Tree만","Hash만"]','["Stack","Queue","Treeのみ","Hashのみ"]',1,'Queue','Queue','같은 거리의 정점을 먼저 처리하는 FIFO가 필요하다.','同じ距離の頂点を先に処理するFIFOが必要。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-10') AND type_no=2;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'크기 N 원형Queue index의 전형적 다음 위치는?','大きさNの循環Queue indexの典型的な次位置は?','["i+N","i%2","(i+1)%N","N-i"]','["i+N","i%2","(i+1)%N","N-i"]',2,'(i+1)%N','(i+1)%N','끝 다음을 0으로 순환시키기 위해 mod N을 쓴다.','末尾の次を0へ循環させるためmod Nを使う。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-10') AND type_no=3;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'BST를 inorder 순회하면?','BSTをinorder巡回すると?','["오름차순","삽입순","무작위","항상 내림차순"]','["昇順","挿入順","random","常に降順"]',0,'오름차순','昇順','left-root-right와 BST 대소관계 때문에 오름차순이다.','left-root-rightとBST大小関係により昇順。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-11') AND type_no=1;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'BST root=50에 30을 삽입할 위치는?','BST root=50へ30を挿入する位置は?','["왼쪽","오른쪽","root교체","불가"]','["左","右","root置換","不可"]',0,'왼쪽','左','30<50이므로 왼쪽으로 내려간다.','30<50なので左へ進む。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-11') AND type_no=2;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'BST가 한쪽으로 완전히 치우치면 탐색 최악은?','BSTが片側へ完全に偏ると探索最悪は?','["O(1)","O(log n)","O(n)","O(n²)"]','["O(1)","O(log n)","O(n)","O(n²)"]',2,'O(n)','O(n)','높이가 n 수준이 되어 연결list처럼 탐색한다.','高さがn程度となりlistのように探索する。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-11') AND type_no=3;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'무가중 그래프에서 최소 간선수 거리를 구할 때 적합한 것은?','重みなしgraphで最小辺数距離を求めるのに適するのは?','["BFS","DFS만","Bubble","Hash"]','["BFS","DFSのみ","Bubble","Hash"]',0,'BFS','BFS','레벨 순 최초 방문이 최소 간선 수를 보장한다.','level順の初回訪問が最小辺数を保証。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-12') AND type_no=1;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'DFS의 대표 구현 구조는?','DFSの代表的実装構造は?','["Queue만","Stack 또는 재귀","Heap만","정렬"]','["Queueのみ","Stackまたは再帰","Heapのみ","sort"]',1,'Stack 또는 재귀','Stackまたは再帰','깊게 들어갔다 되돌아오므로 LIFO 성질을 쓴다.','深く進んで戻るためLIFO性質を使う。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-12') AND type_no=2;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'인접list 기반 BFS/DFS의 시간복잡도는?','隣接list型BFS/DFSの時間計算量は?','["O(1)","O(log V)","O(V+E)","O(VE²)"]','["O(1)","O(log V)","O(V+E)","O(VE²)"]',2,'O(V+E)','O(V+E)','각 정점과 간선을 상수 횟수 확인한다.','各頂点と辺を定数回確認する。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-12') AND type_no=3;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'[5,1,4,2] Bubble 오름차순 1 pass 후는?','[5,1,4,2]をBubble昇順で1 pass後は?','["1,4,2,5","1,5,2,4","5,1,2,4","1,2,4,5"]','["1,4,2,5","1,5,2,4","5,1,2,4","1,2,4,5"]',0,'1,4,2,5','1,4,2,5','인접 교환으로 가장 큰 5가 맨 뒤로 이동한다.','隣接交換で最大5が末尾へ移動する。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-13') AND type_no=1;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'Quick sort 평균/최악 조합은?','Quick sortの平均/最悪の組合せは?','["O(n),O(n)","O(n log n),O(n²)","O(n²),O(log n)","O(log n),O(n)"]','["O(n),O(n)","O(n log n),O(n²)","O(n²),O(log n)","O(log n),O(n)"]',1,'O(n log n), O(n²)','O(n log n), O(n²)','균형분할은 평균 n log n, 극단적 분할은 최악 n².','均衡分割は平均n log n、極端分割は最悪n²。',2,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-13') AND type_no=2;
INSERT OR REPLACE INTO ap_concept_questions SELECT NULL,id,1,'안정 정렬의 의미는?','安定sortの意味は?','["모든 입력 O(n)","동일 key 상대순서 유지","추가 memory 0","재귀 없음"]','["全入力O(n)","同一keyの相対順維持","追加memory 0","再帰なし"]',1,'동일 key 상대순서 유지','同一keyの相対順維持','같은 key를 가진 레코드의 원래 순서를 보존한다.','同じkeyを持つrecordの元の順序を保つ。',1,1 FROM ap_concept_problem_types WHERE concept_id=(SELECT id FROM ap_concepts WHERE concept_code='A-13') AND type_no=3;
